using System;
using System.Collections.Generic;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "StalkingJesterOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/StalkingJester Omen Data")]
public class StalkingJesterOmenData : IncreasePurifyReceivedByAllTargetsOmenData
{
	protected Action omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			List<InventoryItem> starterDiceInvetoryItems = ReferenceSingleton<AssetsReference>.Instance.DrawPool.GetAllInventoryItemDiceFromSpecificTier(ReferenceSingleton<AssetsReference>.Instance.StarterDieTier);
			if (starterDiceInvetoryItems.Count > 0)
			{
				omenInstance.ActivateOmenFeedback();
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
				{
					for (int i = 0; i < starterDiceInvetoryItems.Count; i++)
					{
						ReferenceSingleton<AssetsReference>.Instance.DrawPool.DecreaseDiceAmount(starterDiceInvetoryItems[i].dice, starterDiceInvetoryItems[i].amount);
						ReferenceSingleton<AssetsReference>.Instance.Discard.IncreaseDiceAmount(starterDiceInvetoryItems[i].dice, starterDiceInvetoryItems[i].amount);
					}
				});
			}
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.HasStalkingJesterOmen = true;
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfBattleOmenActions.Add(omenAction);
		base.Initialize(omenInstance);
	}

	protected override int GetAdditionalPurifyAmount()
	{
		string key = ReferenceSingleton<AssetsReference>.Instance.StarterDieTier.name;
		return Mathf.FloorToInt((float)ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceByTypeAmount(onlyFromHand: false, onlyFromDicePool: true)[key] / (float)TriggerAmount) * additionalPurifyAmount;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.HasStalkingJesterOmen = false;
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.StartOfBattleOmenActions.Remove(omenAction);
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), additionalPurifyAmount, TriggerAmount);
	}
}
